function newsletterSection(){return `<section class="newsletter section" id="newsletter" aria-labelledby="newsletter-title"><div><div class="eyebrow">${tr('Keep a little closer','خليك قريب')}</div><h2 id="newsletter-title">${tr('A little news.<br>A lot of community.','شوية أخبار.<br>كتير من اللمة.')}</h2><p>${tr('Upcoming gatherings, campus news and moments from home, in one little letter.','الفعاليات القادمة وأخبار الجامعة ولحظات من البيت في نشرة واحدة.')}</p></div><div class="newsletter-panel"><span class="tag">${tr('NEWSLETTER · COMING SOON','النشرة · قريباً')}</span><form id="newsletter-form"><label for="newsletter-email">${tr('Your email','بريدك الإلكتروني')}</label><div class="newsletter-input-row"><input id="newsletter-email" type="email" required maxlength="254" autocomplete="email" placeholder="you@example.com"><button class="button" type="submit">${tr('Subscribe','اشترك')} </button></div><label class="newsletter-consent"><input type="checkbox" required><span>${tr('I’d like to receive SSO news when the newsletter launches.','أرغب في تلقي أخبار المنظمة عند إطلاق النشرة.')}</span></label><p class="newsletter-note">${tr('Subscriptions open soon. This form does not yet add you to a mailing list.','الاشتراك متاح قريباً. هذا النموذج لا يضيفك لقائمة بريدية بعد.')}</p></form><div id="newsletter-success" hidden role="status"><h3>${tr('Subscriptions are opening soon.','الاشتراكات تُفتح قريباً.')}</h3><p>${tr('You haven’t been subscribed. Follow Instagram for updates while we get the newsletter ready.','لم يتم اشتراكك. تابع إنستغرام للأخبار حتى إطلاق النشرة.')}</p><button class="textlink" id="newsletter-reset">${tr('Try again','جرّب مرة أخرى')} </button></div></div></section>`}
function bindNewsletter(){const f=document.querySelector('#newsletter-form');if(!f)return;f.onsubmit=e=>{e.preventDefault();if(!f.reportValidity())return;f.reset();f.hidden=true;document.querySelector('#newsletter-success').hidden=false};document.querySelector('#newsletter-reset').onclick=()=>{document.querySelector('#newsletter-success').hidden=true;f.hidden=false;document.querySelector('#newsletter-email').focus()}}
